const initSqlJs = require('sql.js');
const fs = require('fs');
async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // List tables
  const tables = db.exec(\"SELECT name FROM sqlite_master WHERE type='table'\");
  const tableNames = tables[0].values.map(r => r[0]);
  console.log('Tables:', tableNames);

  // Search each table for PROD-2DBA15 / Ergonomic Mouse
  for (const t of tableNames) {
    const cols = db.exec('PRAGMA table_info(\"' + t + '\")');
    if (!cols.length) continue;
    const colNames = cols[0].values.map(r => r[1]);
    const clause = colNames.map(c => 'CAST(\"' + c + '\" AS TEXT) LIKE \"%2DBA15%\" OR CAST(\"' + c + '\" AS TEXT) LIKE \"%Ergonomic Mouse%\"').join(' OR ');
    const results = db.exec('SELECT * FROM \"' + t + '\" WHERE ' + clause);
    if (results.length && results[0].values.length) {
      console.log('\n=== Table: ' + t + ' ===');
      console.log('Columns:', colNames.join(', '));
      results[0].values.forEach(row => console.log(row));
    }
  }
}
main();
